insert into public.pathways (id,title,field,qualification,summary,duration,typical_entry,study_topics,job_roles,industries,next_steps,eligibility_note,demand_note,source_urls) values
('btech-aids','BTech in Artificial Intelligence & Data Science','Engineering & Technology','BTech / bachelor''s degree','Uses programming, statistics and machine learning to find patterns in data and build predictive systems. It is not just learning AI tools: mathematics, data quality and software foundations matter.','Usually 4 years','Usually Class 12 with required mathematics/science subjects and an applicable admission route; exact rules vary.',array['Python','Statistics and probability','Data structures','Machine learning','Databases','Data visualisation']::text[],array['Data analyst','Junior data engineer','ML engineer (usually with strong projects/experience)','Business intelligence analyst']::text[],array['IT and software','Finance','Healthcare analytics','Retail','Manufacturing']::text[],array['Check maths eligibility and syllabus depth.','Compare AI&DS with CSE and IT.','Try a beginner Python and statistics project.','Review internships and the actual placement report, not only the highest package.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://jeemain.nta.nic.in/','https://cetcell.mahacet.org/']::text[]),
('btech-it','BTech in Information Technology','Engineering & Technology','BTech / bachelor''s degree','Focuses on building, managing and securing information systems, software, networks and databases. Course overlap with CSE can be substantial, so compare the actual syllabus.','Usually 4 years','Usually Class 12 with required subjects and institution-specific admission criteria.',array['Programming','Web systems','Databases','Networks','Cloud basics','Information security']::text[],array['Software developer','Systems engineer','Cloud support associate','QA engineer','IT analyst']::text[],array['IT services','Software products','Banking technology','Government IT','Telecom']::text[],array['Compare IT and CSE syllabi at each college.','Build one web or database project.','Practise problem solving and communication.','Check role-wise placement data and eligibility.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://jeemain.nta.nic.in/','https://cetcell.mahacet.org/','https://www.ncs.gov.in/']::text[]),
('btech-ece','BTech in Electronics & Telecommunication','Engineering & Technology','BTech / bachelor''s degree','Studies electronic circuits, communication systems, signals and embedded hardware. Careers may span electronics, telecom, testing and software depending on skills.','Usually 4 years','Usually Class 12 with required mathematics/science subjects; check current admission rules.',array['Circuit analysis','Digital electronics','Signals','Communication systems','Embedded systems','Microprocessors']::text[],array['Electronics engineer','Embedded systems trainee','Telecom engineer','Validation/test engineer','Hardware support engineer']::text[],array['Electronics manufacturing','Telecom','Automotive electronics','Defence suppliers','Semiconductors']::text[],array['Try a basic electronics or microcontroller project.','Compare lab facilities and internships.','Ask whether placement figures separate core and IT jobs.','Learn tools used in the chosen subfield.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://jeemain.nta.nic.in/','https://cetcell.mahacet.org/']::text[]),
('btech-electrical','BTech in Electrical Engineering','Engineering & Technology','BTech / bachelor''s degree','Works with electrical power, machines, control systems and energy distribution, from generation to use.','Usually 4 years','Usually Class 12 with required mathematics/science subjects; admission rules vary.',array['Electrical machines','Power systems','Control systems','Power electronics','Protection','Renewable energy']::text[],array['Electrical design trainee','Power systems engineer','Maintenance engineer','Testing engineer','Renewable energy analyst']::text[],array['Power utilities','Manufacturing','Renewable energy','Railways','Building services']::text[],array['Compare core labs and industry links.','Learn electrical safety and relevant CAD/simulation tools.','Research public-sector exams separately from private hiring.','Review local job descriptions.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://jeemain.nta.nic.in/','https://cetcell.mahacet.org/']::text[]),
('btech-chemical','BTech in Chemical Engineering','Engineering & Technology','BTech / bachelor''s degree','Applies chemistry, physics and mathematics to design processes that make materials, fuels, medicines, food and chemicals safely at scale.','Usually 4 years','Usually Class 12 science with required subjects; check college-specific rules.',array['Mass and energy balances','Thermodynamics','Transport phenomena','Reaction engineering','Process control','Plant safety']::text[],array['Process engineer trainee','Production engineer','Quality analyst','Process safety trainee','R&D assistant']::text[],array['Chemicals','Pharmaceuticals','Oil and gas','Food processing','Materials']::text[],array['Check laboratory and industrial training access.','Learn process safety basics.','Compare regional industries and internships.','Check whether roles require specialised further study.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://jeemain.nta.nic.in/','https://cetcell.mahacet.org/']::text[]),
('btech-biotech','BTech in Biotechnology','Engineering & Technology','BTech / bachelor''s degree','Combines biology and engineering to develop or improve biological products and processes. Research roles may need postgraduate study.','Usually 4 years','Usually Class 12 science; subject combinations and admission routes differ.',array['Cell biology','Genetics','Biochemistry','Bioprocess engineering','Bioinformatics','Laboratory methods']::text[],array['Lab technologist trainee','Bioprocess associate','Quality control associate','Research assistant','Bioinformatics trainee']::text[],array['Biopharma','Diagnostics','Agriculture','Food technology','Research']::text[],array['Check the programme''s lab hours and internships.','Distinguish technician roles from research-scientist pathways.','Review postgraduate requirements for desired roles.','Compare course outcomes and lab facilities.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('btech-robotics','BTech in Robotics / Mechatronics','Engineering & Technology','BTech / bachelor''s degree','Combines mechanical systems, electronics, control and programming to create automated machines and robotic systems.','Usually 4 years','Usually Class 12 mathematics/science; course availability and eligibility vary.',array['Mechanics','Sensors and actuators','Control systems','Embedded programming','CAD','Automation']::text[],array['Automation engineer trainee','Robotics technician/engineer','Controls trainee','Mechatronics engineer','Integration engineer']::text[],array['Manufacturing','Automotive','Warehousing','Medical devices','Industrial automation']::text[],array['Inspect labs and real project work.','Try Arduino or simulation projects.','Compare mechanical, E&TC and robotics syllabi.','Check the number of relevant core internships.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://jeemain.nta.nic.in/','https://cetcell.mahacet.org/']::text[]),
('btech-environmental','BTech in Environmental Engineering','Engineering & Technology','BTech / bachelor''s degree','Applies engineering to water treatment, pollution control, waste management and environmental monitoring.','Usually 4 years','Usually Class 12 science/mathematics; check each institution.',array['Water and wastewater','Air pollution','Solid waste','Environmental chemistry','Impact assessment','Monitoring']::text[],array['Environmental engineer trainee','Water-quality analyst','EHS assistant','Sustainability analyst','Environmental consultant trainee']::text[],array['Infrastructure','Manufacturing','Consulting','Utilities','Government projects']::text[],array['Look for fieldwork and lab exposure.','Learn relevant environmental rules and reporting.','Check local government and consulting vacancies.','Compare course accreditation and internships.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('btech-aerospace','BTech in Aerospace Engineering','Engineering & Technology','BTech / bachelor''s degree','Studies aircraft and spacecraft design, propulsion, aerodynamics and structures. Specialist jobs can be competitive and may require advanced study or security eligibility.','Usually 4 years','Usually Class 12 with mathematics and physics; institute-specific eligibility applies.',array['Aerodynamics','Flight mechanics','Propulsion','Structures','Materials','Simulation']::text[],array['Aerospace design trainee','Testing engineer','Simulation analyst','Manufacturing engineer','Research assistant']::text[],array['Aerospace','Defence','Aircraft maintenance/manufacturing','Research','Simulation software']::text[],array['Check labs, internships and alumni outcomes.','Research role-specific eligibility and location constraints.','Build CAD, simulation or robotics projects.','Compare aerospace with mechanical engineering.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('btech-production','BTech in Production / Manufacturing Engineering','Engineering & Technology','BTech / bachelor''s degree','Improves how products are manufactured: process design, quality, productivity, tooling and factory systems.','Usually 4 years','Usually Class 12 mathematics/science; verify institution rules.',array['Manufacturing processes','Operations research','Quality systems','CAD/CAM','Industrial engineering','Supply chain']::text[],array['Production engineer','Quality engineer','Process improvement trainee','Planning engineer','Manufacturing analyst']::text[],array['Automotive','Industrial manufacturing','Consumer products','Aerospace suppliers','Logistics']::text[],array['Compare industry tie-ups and factory visits.','Learn quality and CAD/CAM basics.','Review core-role placement numbers.','Look for practical internships.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('btech-instrumentation','BTech in Instrumentation & Control','Engineering & Technology','BTech / bachelor''s degree','Focuses on measuring, monitoring and controlling industrial processes using sensors, instruments and automation.','Usually 4 years','Usually Class 12 mathematics/science; verify each programme.',array['Sensors','Measurement systems','Control theory','PLC/SCADA basics','Process instrumentation','Calibration']::text[],array['Instrumentation engineer trainee','Control systems trainee','Calibration engineer','Automation support engineer','Service engineer']::text[],array['Process plants','Pharmaceuticals','Energy','Manufacturing','Automation']::text[],array['Check instrument labs and industrial visits.','Learn automation concepts and safety.','Explore internships with plants and system integrators.','Ask how core placements are counted.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('bca','Bachelor of Computer Applications (BCA)','Computing & IT','Undergraduate degree','A computing-focused degree with software, databases and application development. Entry requirements and mathematics rules vary widely.','Often 3 or 4 years depending on programme','Usually after Class 12; check whether mathematics or a specific stream is required.',array['Programming','Web development','Databases','Operating systems','Software engineering','Networks']::text[],array['Junior developer','QA tester','Technical support associate','Web developer','Application support analyst']::text[],array['IT services','Software products','Digital agencies','Business technology']::text[],array['Compare BCA with BTech and BSc Computer Science.','Check curriculum, internships and placement transparency.','Build projects and practise interviews.','Check whether a master''s degree is needed for your goal.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('bsc-cs','BSc Computer Science','Computing & IT','Undergraduate degree','A science degree focused on computing fundamentals, theory and software. It may be a strong route for students interested in technical depth or postgraduate study.','Often 3 or 4 years depending on programme','Usually after Class 12; subject requirements differ by university.',array['Programming','Algorithms','Discrete mathematics','Operating systems','Databases','Computer theory']::text[],array['Software trainee','QA analyst','Research assistant','Technical support','Further study in computing']::text[],array['IT','Research','Education','Software','Public sector']::text[],array['Compare BSc and BTech syllabi.','Check lab access and internship support.','Plan projects alongside coursework.','Verify postgraduate prerequisites for target roles.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('bba','Bachelor of Business Administration (BBA)','Commerce, Business & Management','Undergraduate degree','Introduces management, marketing, operations, finance and organisational behaviour. The degree alone does not guarantee a management job.','Often 3 or 4 years depending on programme','Usually after Class 12; some colleges use entrance tests or interviews.',array['Marketing','Accounting basics','Business communication','Operations','Human resources','Business analytics']::text[],array['Sales/marketing trainee','Operations associate','HR coordinator','Business development associate','Management trainee (role-dependent)']::text[],array['Retail','Consulting support','Banking','Startups','Corporate operations']::text[],array['Compare specialisations and internship quality.','Check total fees and placement median.','Build communication, spreadsheet and project skills.','Look at actual entry-level job descriptions.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('bcom-accounting','BCom in Accounting & Finance','Commerce, Business & Management','Undergraduate degree','Focuses on accounting, reporting, taxation and financial decision-making; can pair with professional qualifications such as CA, CMA or ACCA where suitable.','Often 3 or 4 years depending on programme','Usually after Class 12; check college and professional-course requirements separately.',array['Financial accounting','Cost accounting','Taxation','Auditing','Corporate finance','Excel and reporting']::text[],array['Accounts executive','Audit assistant','Tax assistant','Finance operations associate','Junior analyst']::text[],array['Accounting firms','Banks','Corporate finance','Retail','Shared service centres']::text[],array['Decide whether you want a degree, professional qualification or both.','Practise spreadsheets and accounting software.','Check exam stages, fees and pass rates from official bodies.','Seek internships and practical work experience.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.icai.org/','https://icmai.in/','https://www.ncs.gov.in/']::text[]),
('ca','Chartered Accountancy (CA)','Commerce, Business & Management','Professional qualification','A professional route covering accounting, audit, taxation, financial reporting and business law. It involves staged exams and practical training, so plan for sustained preparation.','Varies; often several years with exams and practical training','Entry route and current rules depend on the official ICAI scheme and prior qualifications.',array['Accounting','Audit','Tax','Company law','Financial reporting','Ethics']::text[],array['Audit associate','Tax consultant','Financial reporting analyst','Internal audit associate','Finance professional']::text[],array['Audit firms','Companies','Financial services','Consulting','Independent practice']::text[],array['Read the latest ICAI course structure.','Map exam stages and training requirements.','Budget fees and realistic study time.','Talk to trainees about day-to-day workload.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.icai.org/']::text[]),
('cs-professional','Company Secretary (CS)','Commerce, Business & Management','Professional qualification','Focuses on company law, governance, compliance and secretarial practice. It is different from a general secretary or administrative assistant role.','Varies by entry route and exam progress','Check the current ICSI entry route and exemptions.',array['Company law','Corporate governance','Compliance','Securities law','Board processes','Business ethics']::text[],array['Company secretary trainee','Compliance associate','Governance analyst','Legal/compliance support']::text[],array['Listed companies','Law firms','Consulting','Financial services']::text[],array['Review official ICSI stages and training.','Compare CS with CA and CMA.','Read actual compliance job descriptions.','Plan internships and professional networking.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.icsi.edu/']::text[]),
('cma','Cost and Management Accountancy (CMA India)','Commerce, Business & Management','Professional qualification','Centres on cost accounting, management accounting, budgeting, performance and strategic finance.','Varies by entry route and exam progress','Check the current ICMAI entry and exam rules.',array['Cost accounting','Budgeting','Performance management','Taxation','Financial strategy','Analytics']::text[],array['Cost accountant trainee','Budget analyst','Costing executive','Finance analyst','Management accounting associate']::text[],array['Manufacturing','Consulting','Corporate finance','Retail','Financial services']::text[],array['Read the official syllabus and exam calendar.','Compare with CA and CS based on the work you want.','Practise Excel and cost analysis.','Check training and practical experience requirements.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://icmai.in/']::text[]),
('economics','BA/BSc Economics','Commerce, Business & Management','Undergraduate degree','Uses economic theory, data and policy analysis to understand markets, jobs, prices and public decisions. Quantitative depth varies by course.','Often 3 or 4 years depending on programme','Usually after Class 12; some programmes strongly prefer or require mathematics.',array['Microeconomics','Macroeconomics','Statistics','Econometrics','Public policy','Research methods']::text[],array['Research assistant','Economic data analyst','Policy associate','Market research analyst','Further study in economics']::text[],array['Research','Banking','Consulting','Government and policy','Market intelligence']::text[],array['Check maths requirements and quantitative content.','Compare BA and BSc syllabi.','Try basic statistics and data analysis.','Review postgraduate requirements for economist roles.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('banking-finance','Banking & Financial Services','Commerce, Business & Management','Degree, diploma or role-specific exam route','A broad area covering customer banking, lending, operations, risk and financial analysis. Public-sector bank recruitment often uses separate competitive exams.','Varies by role and entry route','Depends on the role; graduate-level recruitment exams and employer-specific criteria may apply.',array['Financial products','Accounting basics','Risk','Customer service','Excel','Regulations']::text[],array['Banking associate','Loan operations associate','KYC analyst','Credit analyst trainee','Financial operations associate']::text[],array['Banks','NBFCs','Fintech','Insurance','Shared service centres']::text[],array['Separate degree choices from recruitment exams.','Use official bank recruitment notices.','Build spreadsheet, communication and numerical skills.','Never pay unofficial placement or recruitment fees.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ibps.in/','https://sbi.co.in/web/careers','https://www.ncs.gov.in/']::text[]),
('hotel-management','Hotel & Hospitality Management','Hospitality, Tourism & Services','Degree or diploma','Prepares students for hotel operations, food service, guest experience and event/hospitality work. Shift patterns and practical training are important to understand.','Commonly 1–4 years depending on route','After Class 12 for many degree routes; entrance tests and practical requirements vary.',array['Food production','Front office','Housekeeping operations','Hospitality finance','Guest relations','Event operations']::text[],array['Front office associate','Guest relations executive','Food production trainee','Event coordinator','Hotel operations trainee']::text[],array['Hotels','Restaurants','Cruise and travel','Events','Catering']::text[],array['Check institute recognition and internship terms.','Ask about shift work and placement locations.','Compare fees, hostel and training costs.','Speak with current students and alumni.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://nchm.gov.in/']::text[]),
('mass-communication','Journalism & Mass Communication','Media, Arts & Communication','Degree, diploma or portfolio route','Covers reporting, writing, video, audio, digital media, public relations and communication strategy.','Varies; degrees commonly 3 or 4 years','Usually after Class 12; entrance, portfolio or language requirements vary.',array['Reporting','Media ethics','Writing','Video/audio production','Digital publishing','Research']::text[],array['Content writer','Reporter trainee','Video production assistant','Social media executive','PR assistant']::text[],array['News media','Digital publishing','Advertising','Public relations','Corporate communications']::text[],array['Create a portfolio of writing or media work.','Check internship quality and newsroom exposure.','Compare journalism with advertising/PR.','Review pay and contract realities in entry-level roles.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('teaching','Teacher Education & Teaching','Education & Social Impact','Degree plus role-specific teacher qualification','Teaching routes depend on the level and institution; school teaching may require specific degrees, teacher education and eligibility tests.','Varies by school level and current rules','Requirements depend on school level, subject, state and current NCTE/authority rules.',array['Subject knowledge','Learning science','Lesson planning','Assessment','Classroom management','Inclusive education']::text[],array['Teaching assistant','School teacher (after required qualifications)','Education coordinator','Learning-content developer']::text[],array['Schools','EdTech','Tutoring','Education nonprofits','Training']::text[],array['Identify the age group and subject you want to teach.','Check official qualification and eligibility-test rules.','Get classroom exposure where possible.','Compare government and private-school recruitment routes.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://ncte.gov.in/','https://ctet.nic.in/']::text[]),
('social-work','Social Work (BSW/MSW routes)','Education & Social Impact','Undergraduate/postgraduate degree','Combines community work, social policy, casework and programme delivery. Some specialist roles need postgraduate study or supervised experience.','Often 3–4 years for bachelor''s; further study varies','Usually after Class 12 for BSW; MSW usually requires a bachelor''s degree.',array['Social policy','Community practice','Research','Counselling basics','Programme evaluation','Ethics']::text[],array['Community programme assistant','Casework assistant','NGO project coordinator','Research assistant','CSR programme associate']::text[],array['NGOs','Public services','CSR','Community health','Research']::text[],array['Check field placement hours and supervision.','Understand emotional demands and safeguarding.','Compare NGO, government and CSR work.','Verify role requirements before choosing counselling-related work.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('political-science','Political Science & Public Policy','Arts, Humanities & Social Sciences','Undergraduate degree; further study may help','Studies political institutions, public administration, law, policy and international relations. Careers often require writing, research, exams or postgraduate specialisation.','Often 3 or 4 years depending on programme','Usually after Class 12; requirements vary by university.',array['Political theory','Public administration','Policy research','International relations','Research methods','Constitutional systems']::text[],array['Policy research assistant','Public affairs assistant','Programme associate','Civil-service exam route','Political communications assistant']::text[],array['Think tanks','Government','NGOs','Media','Public affairs']::text[],array['Try policy writing and research.','Separate civil-service exams from degree selection.','Check internships and language/research expectations.','Compare course content and placement evidence.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('english','English, Literature & Writing','Arts, Humanities & Social Sciences','Undergraduate degree','Develops close reading, writing, argument and communication. Career outcomes improve when paired with demonstrable writing, editing, teaching or research skills.','Often 3 or 4 years depending on programme','Usually after Class 12; language and admission rules vary.',array['Literary studies','Critical theory','Writing','Linguistics basics','Research','Editing']::text[],array['Editor assistant','Content writer','Publishing assistant','Communications associate','Teaching route (with required qualifications)']::text[],array['Publishing','Media','Education','Marketing','Communications']::text[],array['Build a writing/editing portfolio.','Try internships in publishing or communications.','Check teacher-qualification requirements if teaching.','Compare academic and applied course options.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('fashion-design','Fashion Design & Apparel','Design & Creative Arts','Degree, diploma or portfolio route','Combines design, textiles, garment construction, trend research and product development. Portfolio and practical work matter.','Varies by programme','After Class 12 for many courses; entrance tests/portfolio may apply.',array['Drawing','Textiles','Pattern making','Garment construction','Fashion communication','Portfolio']::text[],array['Assistant designer','Fashion stylist assistant','Merchandising assistant','Textile design trainee','Costume assistant']::text[],array['Apparel','Retail','Film and media','Textiles','E-commerce']::text[],array['Check studio access and industry projects.','Build a portfolio and test garment-making/design.','Review internship and placement definitions.','Calculate materials and equipment costs.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.nift.ac.in/']::text[]),
('interior-design','Interior Design','Design & Creative Arts','Degree, diploma or portfolio route','Plans interior spaces using function, materials, lighting, accessibility and client needs. Technical drawings and portfolio are important.','Varies; degree routes often 3–4 years','Entry rules vary; some courses use portfolios or aptitude tests.',array['Space planning','Materials','Lighting','CAD/3D tools','Building basics','Presentation']::text[],array['Interior design assistant','CAD drafter','Visualisation artist','Furniture design assistant','Site coordinator']::text[],array['Design studios','Real estate','Retail','Hospitality','Residential projects']::text[],array['Check studio software and site exposure.','Create a small room-planning portfolio.','Understand client-facing and site coordination work.','Compare course fees and material costs.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('animation-vfx','Animation, VFX & Game Art','Design & Creative Arts','Degree, diploma or portfolio route','Uses visual storytelling and digital tools for animation, compositing, modelling, games and motion graphics. A strong portfolio often matters as much as the course title.','Varies by specialisation','Course entry requirements vary; portfolio or aptitude tests may apply.',array['Drawing fundamentals','3D modelling','Animation principles','Compositing','Storyboarding','Portfolio']::text[],array['Junior animator','3D artist','Compositor trainee','Motion graphics designer','Game art assistant']::text[],array['Animation studios','Games','Advertising','Film/TV','E-learning']::text[],array['Try free beginner tools before paying for a course.','Review student portfolios, not only advertisements.','Check hardware/software costs.','Look at recent entry-level job requirements.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('architecture','Architecture (BArch)','Built Environment & Design','Professional bachelor''s degree','Designs buildings and spaces while balancing safety, function, climate, materials, regulations and aesthetics. Professional registration requirements apply.','Commonly 5 years','Specific Class 12 subject requirements, aptitude/entrance rules and current Council of Architecture rules apply.',array['Architectural design','Building construction','Structures','Climate-responsive design','History and theory','Digital modelling']::text[],array['Architectural assistant','Design intern','BIM trainee','Urban design study route','Further professional practice']::text[],array['Architecture firms','Construction','Urban development','Government','Sustainability']::text[],array['Verify current CoA eligibility and entrance rules.','Check studio culture, software and model-making costs.','Compare internships and student work.','Understand registration and practical training requirements.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.coa.gov.in/','https://www.nata.in/']::text[]),
('mbbs','Medicine (MBBS)','Healthcare & Life Sciences','Professional medical degree','Trains doctors in clinical medicine and patient care. Admission is highly regulated and requires the current official entrance and eligibility process.','Typically 5.5 years including internship in India','Requires the current NEET-UG and eligibility requirements; confirm only through official authorities.',array['Anatomy','Physiology','Pathology','Pharmacology','Clinical rotations','Patient communication']::text[],array['Medical intern','Doctor after required registration','Postgraduate specialty route']::text[],array['Hospitals','Clinics','Public health','Research','Medical education']::text[],array['Read current NTA/NMC rules.','Compare total costs and support systems.','Understand training length and clinical responsibility.','Do not rely on unofficial admission agents.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://neet.nta.nic.in/','https://www.nmc.org.in/']::text[]),
('nursing','Nursing','Healthcare & Life Sciences','Degree or diploma depending on route','Provides patient care, monitoring, health education and coordination. Registration and approved-programme requirements are important.','Varies by qualification','Requirements depend on the course, state nursing council and current Indian Nursing Council rules.',array['Anatomy and physiology','Patient care','Pharmacology basics','Clinical practice','Infection control','Communication']::text[],array['Staff nurse after required registration','Community health nurse','Clinical research support','Further specialist nursing route']::text[],array['Hospitals','Clinics','Community health','Public health','Care services']::text[],array['Check approved colleges and clinical placements.','Verify registration eligibility.','Ask about shift work and clinical workload.','Compare total fees and hostel costs.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://indiannursingcouncil.org/']::text[]),
('pharmacy','Pharmacy (DPharm / BPharm routes)','Healthcare & Life Sciences','Diploma or bachelor''s degree','Studies medicines, formulation, quality, dispensing and pharmaceutical science. Different roles have different registration and qualification requirements.','DPharm commonly 2 years; BPharm commonly 4 years','Subject and admission rules vary; check PCI-approved programmes and registration rules.',array['Pharmaceutics','Pharmaceutical chemistry','Pharmacology','Quality assurance','Drug regulations','Clinical pharmacy']::text[],array['Pharmacy assistant/trainee','Quality control trainee','Production associate','Regulatory affairs assistant','Pharmacist after required registration']::text[],array['Pharmacies','Pharma manufacturing','Hospitals','Clinical research','Regulatory affairs']::text[],array['Verify PCI approval and state registration.','Compare DPharm and BPharm outcomes.','Check laboratory and industry training.','Confirm role-specific requirements.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://pci.nic.in/']::text[]),
('physiotherapy','Physiotherapy','Healthcare & Life Sciences','Professional bachelor''s degree','Uses movement, rehabilitation and therapeutic exercise to help people improve function. Clinical placements and professional requirements matter.','Duration and internship depend on current programme rules','Check current recognised programme, internship and registration requirements.',array['Anatomy','Physiology','Biomechanics','Rehabilitation','Exercise therapy','Clinical assessment']::text[],array['Physiotherapy intern','Rehabilitation assistant','Physiotherapist after applicable requirements','Sports rehabilitation route']::text[],array['Hospitals','Rehabilitation centres','Sports','Clinics','Community health']::text[],array['Verify course recognition and clinical hours.','Observe a qualified practitioner if possible.','Compare placements and facilities.','Research the legal scope of practice in your state.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.nca.gov.in/']::text[]),
('agriculture','Agriculture & Agricultural Sciences','Agriculture & Environment','Degree, diploma or vocational route','Covers crop science, soils, plant health, farm systems, agricultural economics and technology. Work may be field-based, lab-based, commercial or research-oriented.','Varies by route','Eligibility and entrance routes vary by institution and state.',array['Soil science','Crop production','Plant pathology','Agricultural economics','Irrigation','Agri-tech']::text[],array['Agriculture field officer trainee','Seed/quality assistant','Agronomy assistant','Agri-sales associate','Research assistant']::text[],array['Agribusiness','Seeds and fertilisers','Food supply chains','Government extension','Agri-tech']::text[],array['Check ICAR/state university admissions.','Ask about farm/field practical work.','Compare public-sector exams with private agribusiness roles.','Explore internships in local agriculture-related organisations.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://icar.org.in/']::text[]),
('veterinary','Veterinary Science','Agriculture & Environment','Professional veterinary degree','Focuses on animal health, diagnosis, surgery, prevention and public health. Admission and registration are regulated.','Typically 5.5 years including internship in India; verify current rules','Check current NEET/VCI/state counselling and eligibility requirements.',array['Animal anatomy','Physiology','Pathology','Surgery','Animal nutrition','Public health']::text[],array['Veterinary intern','Veterinary practitioner after registration','Livestock health officer route','Research assistant']::text[],array['Clinics','Livestock','Public health','Research','Animal welfare']::text[],array['Verify official admission and recognition rules.','Understand clinical placements and animal-handling work.','Compare government and private-sector routes.','Research registration requirements.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://vci.dahd.gov.in/','https://neet.nta.nic.in/']::text[]),
('microbiology','Microbiology','Healthcare & Life Sciences','BSc/BS degree; further study often helps','Studies microorganisms and their roles in health, food, environment and industry. Lab and research careers may require postgraduate qualifications.','Often 3 or 4 years depending on programme','Usually after Class 12 science; subject requirements vary.',array['Microbial biology','Immunology','Lab methods','Biochemistry','Food microbiology','Research methods']::text[],array['Lab assistant','Quality control trainee','Research assistant','Food testing associate','Further study in life sciences']::text[],array['Diagnostics','Food safety','Pharma','Biotechnology','Research']::text[],array['Check laboratory hours and safety training.','Distinguish entry-level lab roles from research careers.','Review postgraduate requirements.','Look for approved internships.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('forensic-science','Forensic Science','Healthcare & Life Sciences','BSc/BS or specialised degree','Applies scientific methods to evidence. Forensic roles may be competitive and specific government posts can require additional exams and eligibility.','Often 3 or 4 years depending on programme','Entry requirements and hiring rules vary by programme and employer.',array['Forensic biology','Chemistry','Evidence handling','Toxicology','Criminalistics','Lab quality']::text[],array['Forensic lab assistant','Evidence technician','Research assistant','Quality analyst','Further specialist study']::text[],array['Forensic laboratories','Government services','Research','Testing laboratories']::text[],array['Check recognised courses and lab facilities.','Read official recruitment notifications for actual posts.','Understand evidence integrity and confidentiality.','Compare forensic science with chemistry/biology routes.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('aviation','Aviation & Airport Operations','Transport & Public Services','Diploma, degree or licensed-training route','Aviation includes airport operations, cabin crew, aircraft maintenance, piloting and logistics; each has distinct medical, licensing and training requirements.','Varies substantially by role','There is no single entry rule; check the regulator and employer requirements for the exact role.',array['Aviation safety','Airport operations','Customer service','Operations planning','Regulations','Role-specific technical training']::text[],array['Airport operations trainee','Ground services associate','Airline customer service','Aviation logistics assistant','Licensed role after required training']::text[],array['Airlines','Airports','Cargo','Ground handling','Travel']::text[],array['Choose a specific aviation role before paying for training.','Verify DGCA and employer rules.','Check medical, licensing and hidden costs.','Avoid guaranteed-job training claims.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.dgca.gov.in/']::text[]),
('sports-science','Sports Science & Physical Education','Sports & Wellbeing','Degree/diploma plus role-specific qualifications','Covers exercise, performance, coaching, fitness and physical education. Professional roles can require certifications, practical experience or teaching qualifications.','Varies by route','Requirements vary by course and role; teaching and clinical roles have additional rules.',array['Exercise physiology','Biomechanics','Training principles','Sports psychology','Injury prevention','Coaching']::text[],array['Fitness trainer','Sports programme assistant','Coach after relevant certification','Physical education teaching route','Performance support assistant']::text[],array['Schools','Gyms','Sports clubs','Rehabilitation','Professional sports']::text[],array['Check practical hours and recognised qualifications.','Get first-aid/safety training where relevant.','Understand income variability in sports work.','Build experience and a portfolio of coaching.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('tourism','Travel & Tourism Management','Hospitality, Tourism & Services','Degree, diploma or vocational route','Covers travel planning, destination operations, customer service, tourism marketing and itinerary management.','Varies by programme','Usually after Class 12 for degree routes; programme requirements vary.',array['Tour operations','Ticketing basics','Customer service','Destination management','Digital marketing','Travel regulations']::text[],array['Travel consultant','Tour operations assistant','Guest experience associate','Destination marketing assistant','Travel coordinator']::text[],array['Travel agencies','Tour operators','Hotels','Events','Tourism boards']::text[],array['Check internships and industry partnerships.','Learn practical booking and customer tools.','Compare seasonal work and salary conditions.','Verify any required certifications.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('diploma-engineering','Engineering Diploma after Class 10','Post-Class-10 Pathways','Polytechnic diploma','A practical technical route after Class 10. It can lead to technician/technologist work, further study, or eligible lateral entry into a degree depending on current rules.','Commonly 3 years; lateral entry routes may exist','After Class 10; branch availability, merit and counselling rules vary by state.',array['Branch-specific engineering','Workshop/lab practice','Technical drawing','Applied mathematics','Industrial training','Safety']::text[],array['Technician','Junior technical assistant','CAD drafter','Service technician','Further study via eligible lateral entry']::text[],array['Manufacturing','Construction','Utilities','Automotive','IT/electronics depending on branch']::text[],array['Compare diploma branches and local polytechnics.','Check AICTE/state approval and lab facilities.','Understand diploma-to-degree eligibility.','Check apprenticeships and real placement data.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.aicte-india.org/','https://dte.maharashtra.gov.in/']::text[]),
('iti-trades','ITI / Industrial Training Certificate','Post-Class-10 Pathways','Trade certificate / vocational training','A hands-on route for specific trades such as electrician, fitter, welder, mechanic or COPA. Trade recognition and apprenticeship opportunities matter.','Often 6 months to 2 years depending on trade','Entry can be after Class 8 or 10 depending on trade; check official institute and trade rules.',array['Trade-specific practice','Workshop safety','Tools and measurement','Basic technical theory','Employability skills','Apprenticeship']::text[],array['Trade apprentice','Technician','Service/repair worker','Workshop assistant','Self-employment after experience']::text[],array['Manufacturing','Maintenance','Construction','Automotive','Utilities']::text[],array['Choose a trade based on local demand and your interests.','Verify NCVT/SCVT affiliation and practical facilities.','Ask about apprenticeship links.','Check safety, tools and certification requirements.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://dgt.gov.in/','https://www.apprenticeshipindia.gov.in/']::text[]),
('class11-12-streams','Choose a Class 11–12 Stream','Post-Class-10 Pathways','Higher secondary education','Science, Commerce and Arts/Humanities are not fixed destinies. Choose based on required subjects for future options, interest, learning strengths and realistic workload.','Usually 2 years','After Class 10; subject combinations and availability depend on the school/board.',array['Stream-specific subjects','Study skills','Career exploration','Projects/practicals','Entrance exam foundations','Communication']::text[],array['Keeps different further-study options open depending on subjects','Builds foundation for vocational or degree routes']::text[],array['Further education','Vocational training','Apprenticeships','Competitive exams']::text[],array['List 3 possible future routes before selecting subjects.','Check prerequisite subjects for those routes.','Compare school quality, commute and costs.','Do not choose a stream only because friends or relatives choose it.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.cbse.gov.in/','https://mahahsscboard.in/']::text[]),
('actuarial-science','Actuarial Science','Commerce, Business & Management','Professional exams plus degree often useful','Uses mathematics, statistics and financial theory to model risk, especially in insurance, pensions and finance. It is highly quantitative and exam-intensive.','Multi-year exam pathway','Check current Institute of Actuaries of India entry and exam requirements; strong mathematics is important.',array['Probability','Statistics','Financial mathematics','Risk modelling','Economics','Programming/data']::text[],array['Actuarial analyst','Risk analyst','Pricing analyst','Insurance analytics associate']::text[],array['Insurance','Consulting','Pensions','Banking','Risk management']::text[],array['Try probability/statistics before committing.','Review official exam structure and costs.','Compare actuarial with economics and finance.','Build spreadsheet and programming skills.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.actuariesindia.org/']::text[]),
('digital-marketing','Digital Marketing & E-commerce','Media, Arts & Communication','Degree, diploma, certificate or portfolio route','Combines content, search, analytics, advertising and online sales. Employers value demonstrable campaign results and ethical data practices.','Varies by route','Many routes accept varied educational backgrounds; check role-specific requirements.',array['Content strategy','SEO basics','Analytics','Paid campaigns','E-commerce','Copywriting']::text[],array['Digital marketing executive','SEO assistant','Content strategist trainee','Performance marketing assistant','E-commerce operations associate']::text[],array['Agencies','Retail','Startups','Media','Corporate marketing']::text[],array['Build a small project or portfolio.','Learn analytics and privacy basics.','Check certificate quality before paying.','Compare internship tasks with actual job descriptions.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('human-resources','Human Resources & People Operations','Commerce, Business & Management','Degree/diploma plus practical experience','Supports recruitment, onboarding, employee records, learning and workplace processes. Communication, confidentiality and employment-law awareness matter.','Varies by programme','Employers may prefer business, psychology or related degrees; requirements vary.',array['Organisational behaviour','Recruitment','HR operations','Employment basics','Data and spreadsheets','Communication']::text[],array['HR coordinator','Recruitment sourcer','People operations assistant','Learning coordinator','HR analyst trainee']::text[],array['IT','Manufacturing','Healthcare','Retail','Consulting']::text[],array['Try a recruitment or people-analytics project.','Learn spreadsheet and communication skills.','Understand confidentiality and fair hiring.','Review entry-level role requirements.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('supply-chain','Supply Chain & Logistics','Commerce, Business & Management','Degree/diploma or role-based route','Plans how goods move from suppliers to customers, including inventory, procurement, transport and operations analytics.','Varies by programme','Entry requirements vary; business, engineering and logistics programmes may all lead into this field.',array['Operations','Inventory','Procurement','Logistics','Excel/data','Quality']::text[],array['Logistics coordinator','Procurement assistant','Inventory analyst trainee','Operations associate','Supply chain analyst trainee']::text[],array['Manufacturing','E-commerce','Retail','Transport','Pharmaceuticals']::text[],array['Look for operations internships.','Practise spreadsheets and process mapping.','Check shift/warehouse expectations.','Compare course fees with employer-recognised skills.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('psychology-counselling','Counselling & Applied Psychology Pathway','Arts, Humanities & Social Sciences','Degree plus role-specific postgraduate training/registration','Psychology degrees do not automatically qualify someone to practise as a clinical psychologist or counsellor. Requirements depend on the exact professional role and current regulations.','Several years depending on specialisation','Undergraduate entry usually after Class 12; specialist practice requires checking current regulator requirements.',array['Psychological theory','Research methods','Ethics','Listening skills','Assessment basics','Supervised practice']::text[],array['Research assistant','Wellbeing programme assistant','HR/people roles','Specialist practice only after required training']::text[],array['Education','Research','Community organisations','Healthcare subject to qualifications','Workplaces']::text[],array['Decide whether you want research, HR, education or clinical practice.','Check current RCI/other applicable rules for clinical roles.','Look for supervised placements and ethics training.','Avoid courses promising instant professional qualification.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://rehabcouncil.nic.in/']::text[]),
('civil-services','Civil Services & Government Exams','Transport & Public Services','Degree plus competitive examination route','A recruitment route rather than a single degree. Eligibility, syllabus, age limits and selection stages depend on the specific exam and current notification.','Varies; preparation can take multiple years','Many major exams require a bachelor''s degree; check the exact official notification.',array['General studies','Reasoning','Writing','Current affairs','Subject knowledge','Interview preparation']::text[],array['Civil servant after selection','Government officer through specific recruitment','Public-sector role depending on exam']::text[],array['Government','Public administration','Regulators','Public-sector organisations']::text[],array['Choose the specific exam first.','Read the latest official notification and syllabus.','Protect degree performance and backup options.','Use a realistic study plan rather than buying every course.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://upsc.gov.in/','https://www.ncs.gov.in/']::text[]),
('law-integrated','Integrated Law (BA LLB / BBA LLB)','Law & Public Policy','Integrated professional degree','Combines law with humanities or business studies. Careers include litigation, corporate law, compliance and policy, each with different skill and practice requirements.','Commonly 5 years after Class 12','Entrance tests and eligibility depend on the institution; verify current official notices.',array['Legal reasoning','Constitutional law','Contracts','Research and writing','Moot court','Internships']::text[],array['Legal intern','Legal researcher','Law firm associate after qualification','Compliance analyst','Policy assistant']::text[],array['Law firms','Courts','Companies','Government','NGOs']::text[],array['Compare colleges by teaching, internships and total cost.','Check the official entrance route.','Start legal reading and writing practice.','Understand enrolment and professional requirements.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://consortiumofnlus.ac.in/','https://www.barandbench.com/']::text[]),
('product-design','Product / UX Design','Design & Creative Arts','Degree, diploma or portfolio route','Researches user needs and designs digital or physical products that are useful, usable and accessible. A portfolio showing process matters.','Varies by programme','Entry routes vary; portfolio, aptitude tests or design entrance exams may apply.',array['User research','Interaction design','Prototyping','Accessibility','Visual design','Usability testing']::text[],array['UX designer trainee','UI designer','Product design intern','UX researcher assistant','Interaction designer']::text[],array['Software products','Consulting','Finance technology','Healthcare technology','Design agencies']::text[],array['Try redesigning a small everyday experience.','Learn wireframing and usability testing.','Compare UX with graphic design.','Build a case-study portfolio and seek feedback.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('environmental-science','Environmental Science','Agriculture & Environment','BSc/BS; further study may help','Studies ecosystems, pollution, climate and conservation using fieldwork, lab work and data. Some professional roles require specialised qualifications.','Often 3 or 4 years depending on programme','Usually after Class 12; science subject requirements vary by university.',array['Ecology','Climate science','Environmental chemistry','GIS basics','Field methods','Data analysis']::text[],array['Field assistant','Environmental monitoring assistant','Sustainability associate','Research assistant','GIS trainee']::text[],array['Consulting','Conservation','Government','Research','Corporate sustainability']::text[],array['Check fieldwork and laboratory components.','Learn data/GIS tools.','Review role-specific qualification requirements.','Seek verified internships and volunteering.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('finance-analytics','Finance & Business Analytics','Commerce, Business & Management','Degree plus analytical tools/experience','Uses business data to support budgeting, forecasting, investment or operational decisions. Quantitative expectations depend on the role.','Varies by route','Employers accept varied degrees for some analyst roles; maths, tools and experience matter.',array['Financial statements','Excel','Statistics','Data visualisation','Business metrics','Presentation']::text[],array['Financial analyst trainee','Business analyst','Reporting analyst','FP&A associate','Operations analyst']::text[],array['Banking','Consulting','Corporate finance','Retail','Fintech']::text[],array['Build a spreadsheet dashboard project.','Learn accounting and basic statistics.','Read real entry-level job descriptions.','Check whether a role needs professional certification.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('library-information','Library & Information Science','Arts, Humanities & Social Sciences','Degree/diploma depending on role','Organises information resources, supports research and manages physical or digital collections. Some librarian roles require specific library-science qualifications.','Varies by qualification','Role requirements vary; librarian positions may require a recognised library-science qualification.',array['Cataloguing','Information organisation','Digital repositories','Research support','Archives','Metadata']::text[],array['Library assistant','Digital repository assistant','Information services associate','Archive assistant','Further librarian qualification route']::text[],array['Schools','Universities','Public libraries','Archives','Research institutions']::text[],array['Check qualifications for the exact role.','Explore digital library and research tools.','Review public recruitment notices.','Compare practical placements and course recognition.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[]),
('entrepreneurship','Entrepreneurship & Small Business','Commerce, Business & Management','No single required degree; education can support the route','Builds a business by identifying a real problem, testing a solution, understanding costs and serving customers. A degree is optional, but financial and legal basics are not.','Ongoing; start small and test','No universal degree requirement; legal, tax and sector rules still apply.',array['Customer discovery','Pricing and costs','Sales','Cash flow','Operations','Compliance']::text[],array['Founder','Small-business operator','Freelancer','Family-business successor','Startup operations associate']::text[],array['Many sectors','Local services','E-commerce','Technology','Creative businesses']::text[],array['Interview potential customers before spending money.','Make a simple cost and cash-flow plan.','Test a small version first.','Learn the relevant registration, tax and consumer rules.']::text[],'Eligibility, accreditation, entrance tests, fees and professional licensing vary by institution, state and admission year. Verify the current rules on the official college or regulator website before applying.','Job prospects vary by location, skills, experience and economic conditions. Treat job titles and sectors as examples, not placement guarantees; check current vacancies and verified placement reports.',array['https://www.ncs.gov.in/','https://www.nirfindia.org/']::text[])
